#!/bin/bash
# Uninstall script for Facebook Messenger
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Facebook Messenger..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Facebook Messenger if running..."
pkill -f "Facebook Messenger" 2>/dev/null || true

# Remove /Applications/Messenger.app
echo "Removing /Applications/Messenger.app..."
if [ -d "/Applications/Messenger.app" ]; then
    rm -rf "/Applications/Messenger.app" 2>/dev/null || true
elif [ -f "/Applications/Messenger.app" ]; then
    rm -f "/Applications/Messenger.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Messenger
echo "Removing $HOME/Library/Application Support/Messenger..."
if [ -d "$HOME/Library/Application Support/Messenger" ]; then
    rm -rf "$HOME/Library/Application Support/Messenger" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Messenger" ]; then
    rm -f "$HOME/Library/Application Support/Messenger" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Messenger
echo "Removing $HOME/Library/Caches/Messenger..."
if [ -d "$HOME/Library/Caches/Messenger" ]; then
    rm -rf "$HOME/Library/Caches/Messenger" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Messenger" ]; then
    rm -f "$HOME/Library/Caches/Messenger" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Messenger
echo "Removing $HOME/Library/Logs/Messenger..."
if [ -d "$HOME/Library/Logs/Messenger" ]; then
    rm -rf "$HOME/Library/Logs/Messenger" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Messenger" ]; then
    rm -f "$HOME/Library/Logs/Messenger" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
